<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { CalendarPlus, Check, RefreshCw, Scale, Settings2 } from 'lucide-vue-next';import { ElMessage } from 'element-plus';import { useRoute } from 'vue-router';import { api } from '../api';import AnalyticsChart from '../components/AnalyticsChart.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import type { AnalyticsOptions, EvaluationAppeal, EvaluationIndicator, EvaluationItem, EvaluationTask, PageData } from '../types';
const route=useRoute(),session=useSessionStore(),loading=ref(false),tasks=ref<EvaluationTask[]>([]),evaluations=ref<EvaluationItem[]>([]),appeals=ref<EvaluationAppeal[]>([]),indicators=ref<EvaluationIndicator[]>([]),options=reactive<AnalyticsOptions>({enterprises:[],organizations:[],vehicles:[],accidents:[]}),detail=ref<any>(null),drawer=ref(false),createDialog=ref(false),appealDialog=ref(false),configDrawer=ref(false);const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');const portalMode=computed(()=>route.path.endsWith('/appeals')?'appeals':route.path.endsWith('/history')?'history':'current');const form=reactive({name:'',periodType:'MONTHLY',dates:[] as string[],organizationId:''});const appealForm=reactive({reason:'',evidence:''});const gradeType=(g:string)=>g==='A'?'success':g==='B'?'primary':g==='C'?'warning':'danger';const statusText=(v:string)=>({PUBLISHED:'已发布',COMPLETED:'待发布',RUNNING:'计算中',DRAFT:'草稿',SUBMITTED:'待复核',ACCEPTED:'已受理',REJECTED:'已驳回',UNDER_REVIEW:'重新核定中'} as any)[v]??v;
const radarOption=computed(()=>({radar:{radius:'62%',indicator:[{name:'安全',max:100},{name:'合规',max:100},{name:'运行',max:100}]},series:[{type:'radar',data:detail.value?[{value:[detail.value.safetyScore,detail.value.complianceScore,detail.value.operationScore],areaStyle:{color:'rgba(49,95,145,.2)'},lineStyle:{color:'#315f91'},itemStyle:{color:'#315f91'}}]:[]}]}));
async function load(){
  loading.value=true;
  try{
    if(isEnterprise.value){
      if(portalMode.value==='appeals'){const r=await api<PageData<EvaluationAppeal>>('/analytics/appeals?page=1&pageSize=50');appeals.value=r.items}
      else{const r=await api<PageData<EvaluationItem>>('/analytics/evaluations?page=1&pageSize=50');evaluations.value=portalMode.value==='current'?r.items.slice(0,1):r.items}
    }else{
      const [t,e,a]=await Promise.all([api<PageData<EvaluationTask>>('/analytics/evaluation/tasks?page=1&pageSize=30'),api<PageData<EvaluationItem>>('/analytics/evaluations?page=1&pageSize=50'),api<PageData<EvaluationAppeal>>('/analytics/appeals?page=1&pageSize=50&status=SUBMITTED')]);
      tasks.value=t.items;evaluations.value=e.items;appeals.value=a.items;
    }
  }catch(e){ElMessage.error(e instanceof Error?e.message:'评价数据加载失败')}finally{loading.value=false}
}
async function openEvaluation(id:string){detail.value=await api<any>(`/analytics/evaluations/${id}`);drawer.value=true}
async function createTask(){await api('/analytics/evaluation/tasks',{method:'POST',body:JSON.stringify({name:form.name,periodType:form.periodType,periodStart:form.dates[0],periodEnd:form.dates[1],organizationId:form.organizationId||undefined})});ElMessage.success('评价计算已完成，请复核后发布');createDialog.value=false;await load()}
async function publish(id:string){await api(`/analytics/evaluation/tasks/${id}/publish`,{method:'POST'});ElMessage.success('评价结果已发布');await load()}
async function loadConfig(){indicators.value=await api<EvaluationIndicator[]>('/analytics/evaluation/config');configDrawer.value=true}
async function submitAppeal(){await api(`/analytics/evaluations/${detail.value.id}/appeals`,{method:'POST',body:JSON.stringify(appealForm)});ElMessage.success('申诉已提交');appealDialog.value=false;drawer.value=false;await load()}
async function review(item:EvaluationAppeal,action:'ACCEPT'|'REJECT'){await api(`/analytics/appeals/${item.id}/review`,{method:'POST',body:JSON.stringify({action,comment:action==='ACCEPT'?'证据已受理，进入重新核定。':'现有证据不足以调整原评价。'})});ElMessage.success('申诉复核完成');await load()}
onMounted(async()=>{if(!isEnterprise.value)Object.assign(options,await api<AnalyticsOptions>('/analytics/options'));await load()});watch(()=>route.path,load);
</script>
<template><PageHeader :title="isEnterprise?(portalMode==='appeals'?'评价申诉':portalMode==='history'?'历史评价':'本期评价'):'企业评价'" :description="isEnterprise?'查看评分依据、评价结论及申诉处理进度。':'以可配置指标自动计算企业得分，复核后发布并支持申诉闭环。'"><template v-if="!isEnterprise"><el-button :icon="Settings2" @click="loadConfig">指标规则</el-button><el-button type="primary" :icon="CalendarPlus" @click="createDialog=true">发起评价</el-button></template><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><template v-if="!isEnterprise"><section class="phase6-panel" v-loading="loading"><header><div><strong>评价任务</strong><span>计算完成后需人工复核并发布</span></div><b>{{tasks.length}} 个周期</b></header><el-table :data="tasks"><el-table-column label="任务" min-width="280"><template #default="{row}"><div class="identity-cell"><strong>{{row.name}}</strong><span>{{row.businessNo}}</span></div></template></el-table-column><el-table-column label="评价周期" width="220"><template #default="{row}">{{row.periodStart.slice(0,10)}} 至 {{row.periodEnd.slice(0,10)}}</template></el-table-column><el-table-column label="企业数" width="90"><template #default="{row}">{{row._count.evaluations}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-if="row.status==='COMPLETED'" link type="primary" @click="publish(row.id)">发布结果</el-button><span v-else class="muted">{{row.createdByName}}</span></template></el-table-column></el-table></section><section class="phase6-panel"><header><div><strong>企业评价结果</strong><span>按综合得分与风险等级实施差异化监管</span></div></header><el-table :data="evaluations"><el-table-column label="企业" min-width="220"><template #default="{row}"><div class="identity-cell"><strong>{{row.enterprise.name}}</strong><span>{{row.task.name}}</span></div></template></el-table-column><el-table-column label="综合得分" width="120"><template #default="{row}"><b class="score-number">{{row.totalScore}}</b></template></el-table-column><el-table-column label="等级" width="90"><template #default="{row}"><el-tag :type="gradeType(row.grade)">{{row.grade}} 级</el-tag></template></el-table-column><el-table-column label="安全 / 合规 / 运行" width="210"><template #default="{row}">{{row.safetyScore}} / {{row.complianceScore}} / {{row.operationScore}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{statusText(row.status)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="openEvaluation(row.id)">查看依据</el-button></template></el-table-column></el-table></section><section v-if="appeals.length" class="phase6-panel"><header><div><strong>待复核申诉</strong><span>基于证据完成受理或驳回</span></div></header><el-table :data="appeals"><el-table-column label="企业" prop="enterprise.name" min-width="190"/><el-table-column label="申诉理由" prop="reason" min-width="280" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}">{{statusText(row.status)}}</template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><template v-if="row.status==='SUBMITTED'"><el-button link type="primary" @click="review(row,'ACCEPT')">受理</el-button><el-button link type="danger" @click="review(row,'REJECT')">驳回</el-button></template></template></el-table-column></el-table></section></template><template v-else><section v-if="portalMode!=='appeals'" class="evaluation-cards" v-loading="loading"><article v-for="x in evaluations" :key="x.id" class="evaluation-card"><header><span>{{x.task.name}}</span><el-tag :type="gradeType(x.grade)">{{x.grade}} 级</el-tag></header><div class="evaluation-score"><strong>{{x.totalScore}}</strong><span>综合得分</span></div><div class="dimension-bars"><label>安全 <el-progress :percentage="x.safetyScore" :stroke-width="7"/></label><label>合规 <el-progress :percentage="x.complianceScore" :stroke-width="7"/></label><label>运行 <el-progress :percentage="x.operationScore" :stroke-width="7"/></label></div><p>{{x.conclusion}}</p><el-button type="primary" plain @click="openEvaluation(x.id)">查看评分依据</el-button></article><el-empty v-if="!evaluations.length" description="暂无已发布评价"/></section><section v-else class="phase6-panel" v-loading="loading"><header><div><strong>申诉记录</strong><span>跟踪提交、复核与结果状态</span></div></header><el-table :data="appeals"><el-table-column label="申诉编号" prop="businessNo" width="180"/><el-table-column label="评价周期" min-width="220"><template #default="{row}">{{row.evaluation.task.name}}</template></el-table-column><el-table-column label="申诉理由" prop="reason" min-width="300"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='ACCEPTED'?'success':row.status==='REJECTED'?'danger':'warning'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="复核意见" prop="reviewComment" min-width="260"/></el-table></section></template><el-drawer v-model="drawer" title="评价详情与评分依据" size="680px"><template v-if="detail"><div class="evaluation-detail-head"><div><span>综合得分</span><strong>{{detail.totalScore}}</strong><el-tag :type="gradeType(detail.grade)">{{detail.grade}} 级 · {{detail.riskLevel}}</el-tag></div><AnalyticsChart :option="radarOption" height="220px"/></div><p class="conclusion-box">{{detail.conclusion}}</p><el-table :data="detail.breakdown"><el-table-column label="评价指标" prop="name" min-width="150"/><el-table-column label="权重" width="70"><template #default="{row}">{{row.weight}}%</template></el-table-column><el-table-column label="指标值" prop="value" width="90"/><el-table-column label="得分" prop="score" width="75"/><el-table-column label="命中规则" prop="rule" min-width="130"/></el-table><el-button v-if="isEnterprise&&detail.status==='PUBLISHED'&&!detail.appeals?.some((x:any)=>x.status==='SUBMITTED')" class="appeal-button" :icon="Scale" @click="appealDialog=true">对本期结果发起申诉</el-button></template></el-drawer><el-dialog v-model="createDialog" title="发起企业评价" width="560px"><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="form.name" placeholder="例如：2026 年 9 月企业综合评价"/></el-form-item><div class="form-grid"><el-form-item label="周期类型"><el-select v-model="form.periodType"><el-option label="日报" value="DAILY"/><el-option label="周报" value="WEEKLY"/><el-option label="月报" value="MONTHLY"/></el-select></el-form-item><el-form-item label="评价组织"><el-select v-model="form.organizationId" placeholder="当前组织"><el-option v-for="x in options.organizations" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></div><el-form-item label="评价周期"><el-date-picker v-model="form.dates" type="daterange" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="createDialog=false">取消</el-button><el-button type="primary" :icon="Check" @click="createTask">计算评价</el-button></template></el-dialog><el-dialog v-model="appealDialog" title="提交评价申诉" width="560px"><el-form label-position="top"><el-form-item label="申诉理由"><el-input v-model="appealForm.reason" type="textarea" :rows="4"/></el-form-item><el-form-item label="证据说明"><el-input v-model="appealForm.evidence" type="textarea" :rows="3" placeholder="填写证明材料名称、数据来源或核验线索"/></el-form-item></el-form><template #footer><el-button @click="appealDialog=false">取消</el-button><el-button type="primary" @click="submitAppeal">提交申诉</el-button></template></el-dialog><el-drawer v-model="configDrawer" title="评价指标与评分规则" size="760px"><div class="weight-summary"><span>启用指标 {{indicators.filter(x=>x.status==='ACTIVE').length}} 项</span><strong>权重合计 {{indicators.filter(x=>x.status==='ACTIVE').reduce((s,x)=>s+x.weight,0)}}%</strong></div><el-collapse><el-collapse-item v-for="x in indicators" :key="x.id" :title="`${x.name} · ${x.weight}%`"><p class="muted">{{x.description}}</p><el-table :data="x.rules" size="small"><el-table-column label="规则" prop="label"/><el-table-column label="最低值" prop="minValue" width="90"/><el-table-column label="最高值" prop="maxValue" width="90"/><el-table-column label="得分" prop="score" width="80"/></el-table></el-collapse-item></el-collapse></el-drawer></template>
